const MEASURE_COLUMNS = [
  // pageviews (migration 005) is what makes a row exist at all before any experiment runs: it is both
  // a measure and the fallback denominator behind cta_ctr / buy_click_rate / purchase_rate while an
  // arm has no exposures. cms-agent's engagement.v1 metric vector carries it under the same name.
  "pageviews",
  "exposures",
  "sessions",
  "completion_rate",
  "cta_ctr",
  "buy_click_rate",
  "purchase_rate",
  "revenue_cents",
  "p75_dwell_ms",
] as const;

export function shapeObjectRow(row: Record<string, unknown>): ObjectRollupRow {
  return {
    object_id: String(row.object_id ?? ""),
    variant_id: String(row.variant_id ?? ""),
    day: toDay(row.day),
    ...shapeMeasures(row),
  };
}
